import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../models/available_slot.dart';import '../../providers/auth_providers.dart';import '../../providers/dashboard_providers.dart';import '../../widgets/async_content.dart';import '../../widgets/page_header.dart';import '../../widgets/status_badge.dart';import 'slot_form_dialog.dart';
class AvailabilityScreen extends ConsumerWidget{const AvailabilityScreen({super.key});String dt(DateTime d)=>'${d.year}/${d.month.toString().padLeft(2,'0')}/${d.day.toString().padLeft(2,'0')} ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
Future<void> save(BuildContext context,WidgetRef ref,[AvailableSlot? old])async{final value=await showDialog<AvailableSlot>(context:context,builder:(_)=>SlotFormDialog(initial:old));if(value==null)return;try{final id=ref.read(shopIdProvider).value;if(id==null)return;await ref.read(dashboardRepositoryProvider).saveSlot(id,value);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('空き枠を保存しました')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('保存できませんでした: $e')));}}
@override Widget build(BuildContext context,WidgetRef ref)=>SingleChildScrollView(padding:EdgeInsets.all(MediaQuery.sizeOf(context).width<600?16:32),child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1180),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[PageHeader(title:'空き枠',subtitle:'予約可能な日時と募集人数を管理します。',action:FilledButton.icon(onPressed:()=>save(context,ref),icon:const Icon(Icons.add),label:const Text('空き枠を登録'))),const SizedBox(height:24),AsyncContent(value:ref.watch(slotsProvider),builder:(slots){if(slots.isEmpty)return const _Empty();return Column(children:slots.map((s)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Card(color:s.isPast?Colors.grey.shade100:null,child:Padding(padding:const EdgeInsets.all(20),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.event_available,color:s.isPast?Colors.grey:Theme.of(context).colorScheme.primary),const SizedBox(width:16),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Wrap(spacing:10,runSpacing:8,crossAxisAlignment:WrapCrossAlignment.center,children:[Text('${dt(s.startAt)} 〜 ${dt(s.endAt).split(' ').last}',style:const TextStyle(fontSize:17,fontWeight:FontWeight.bold)),_badge(s)]),const SizedBox(height:8),Text('${s.menuName} ・ 担当 ${s.staffName}'),Text('残り ${s.remainingCapacity} / ${s.capacity}名${s.memo.isEmpty?'':' ・ ${s.memo}'}',style:TextStyle(color:Colors.blueGrey.shade600))])),PopupMenuButton<String>(onSelected:(v)async{if(v=='edit')save(context,ref,s);else{final yes=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('空き枠を削除しますか？'),content:const Text('この操作は取り消せません。'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('キャンセル')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('削除'))]));if(yes==true){final id=ref.read(shopIdProvider).value;if(id!=null)await ref.read(dashboardRepositoryProvider).deleteSlot(id,s.id);}}},itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('編集')),PopupMenuItem(value:'delete',child:Text('削除'))])]))))).toList());})]))));
Widget _badge(AvailableSlot s){if(s.isPast)return const StatusBadge('終了',color:Colors.grey);return switch(s.status){SlotStatus.open=>const StatusBadge('募集中',color:Colors.green),SlotStatus.full=>const StatusBadge('満席',color:Colors.orange),SlotStatus.closed=>const StatusBadge('終了',color:Colors.grey)};}}
class _Empty extends StatelessWidget{const _Empty();@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(48),child:Center(child:Column(children:[Icon(Icons.event_busy_outlined,size:52,color:Colors.blueGrey.shade300),const SizedBox(height:12),const Text('空き枠はまだありません',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('「空き枠を登録」から最初の枠を追加してください。')]))));}
